<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import SidebarNavigation from './components/SidebarNavigation.vue'
import QuestionBankManagement from './components/QuestionBankManagement.vue'
import TreatmentPlanDetail from './components/TreatmentPlanDetail.vue'
import TreatmentPlanManagement from './components/TreatmentPlanManagement.vue'
import './customer-archive.css'
import './modal-shell.css'

type Role = 'hq' | 'reviewer' | 'finance' | 'production' | 'franchisee' | 'admin'
type CaseStatus = '待补资料' | '待审核' | '已生效' | '待支付' | '待生产' | '生产中' | '待质检' | '待发货' | '运输中' | '已签收' | '复测中' | '已完成'
interface Formula { skuCode:string; name:string; ratio:number; dosage:string; rationale:string; machineParams:string; valid:boolean; stockAvailable:boolean }
interface Case { id:string; customer:string; phone:string; store:string; franchisee:string; status:CaseStatus; risk:string; planId:string; planVersion:string; createdAt:string; reportStatus:string; paid:boolean; qualityReleased:boolean; formula:Formula[]; timeline:Array<{time:string;title:string;description:string}> }
interface CustomerRecord { id:string; name:string; phone:string; gender:'男'|'女'|'未知'; birthday:string; source:string; advisor:string; store:string; level:'标准'|'VIP'|'高净值'; status:'正常'|'停用'; tags:string[] }
type ReportStatus = '暂存'|'测评中'|'已完成'
interface ReportAttachment { name:string; type:string }
interface AssessmentReport { id:string; customerId:string; customerName:string; questionnaireVersion:string; description:string; sleepQuality:string; energyLevel:string; exerciseFrequency:string; dietStructure:string; primaryNeed:string; historyNote:string; advisorSummary:string; attachments:ReportAttachment[]; crossBorder:boolean; realName:string; realPhone:string; idCard:string; deliveryAddress:string; status:ReportStatus; assessedAt:string }
const api = async <T,>(path:string, init:RequestInit = {}, role = currentRole.value) => {
  const r = await fetch(path, { ...init, headers: { 'content-type':'application/json', authorization:`Bearer ${role}`, ...(init.headers||{}) } })
  const json = await r.json(); if (!r.ok) throw new Error(json.message || '操作失败'); return json.data as T
}
const currentRole = ref<Role>('hq')
const page = ref('工作台')
const cases = ref<Case[]>([]); const dashboard = ref<any>({ cards: [], messages: [] }); const notice = ref('')
const active = ref<Case | null>(null); const activeCustomer = ref<CustomerRecord | null>(null); const activeReport = ref<AssessmentReport | null>(null); const modal = ref<'review'|'fulfill'|'resource'|'customer'|'report'|''>(''); const action = ref('produce'); const reviewApproved = ref(true); const reviewComment = ref('专业审核通过，建议按方案执行。')
const customers = ref<CustomerRecord[]>([])
const archiveKeyword = ref(''); const archiveStatus = ref(''); const archiveStore = ref(''); const archiveAdvisor = ref(''); const archiveTag = ref('')
const customerMode = ref<'create'|'edit'>('create')
const tagOptions = ['高消费力','中消费力','满意度高','待回访','复测意向']
const blankCustomer = (): CustomerRecord => ({ id:'', name:'', phone:'', gender:'未知', birthday:'', source:'门店扫码', advisor:'陈顾问', store:'上海静安体验店', level:'标准', status:'正常', tags:[] })
const customerDraft = ref<CustomerRecord>(blankCustomer())
const tagKeyword = ref('')
const reports = ref<AssessmentReport[]>([])
const reportForPlan = ref<AssessmentReport | null>(null)
const reportMode = ref<'create'|'edit'>('create')
const reportFormVisible = ref(false)
const blankReport = (): AssessmentReport => ({ id:'', customerId:'', customerName:'', questionnaireVersion:'V1.0', description:'', sleepQuality:'', energyLevel:'', exerciseFrequency:'', dietStructure:'', primaryNeed:'', historyNote:'', advisorSummary:'', attachments:[], crossBorder:false, realName:'', realPhone:'', idCard:'', deliveryAddress:'', status:'暂存', assessedAt:'' })
const reportDraft = ref<AssessmentReport>(blankReport())
const roles: Array<[Role,string]> = [['hq','总部运营'],['reviewer','专业审核人'],['finance','财务专员'],['production','生产履约'],['franchisee','加盟商店员'],['admin','平台管理员']]
const groups: Array<[string, string[]]> = [
  ['工作台',[]],
  ['顾客中心',['顾客档案']],
  ['测评中心',['测评报告','治疗方案','测评题库','题目管理']],
  ['订单中心',['订单管理','收款管理','订单履约']],
  ['加盟中心',['加盟商管理','订货单管理']],
  ['生产中心',['排产任务','生产设备']],
  ['库存管理',['SKU管理','库存台账','商品分类','供应商管理']],
  ['经营分析',[]],
  ['系统设置',['设备集成','大模型配置','部门管理','人员管理','角色管理','菜单管理','参数管理']],
]
const isCasePage = computed(() => ['测评报告','治疗方案','订单管理','收款管理','订单履约','加盟商管理','订货单管理','排产任务','生产设备'].includes(page.value))
const title = computed(() => page.value)
const customerStores = computed(() => [...new Set(customers.value.map(item => item.store))])
const customerAdvisors = computed(() => [...new Set(customers.value.map(item => item.advisor))])
const filteredTagOptions = computed(() => tagOptions.filter(tag => tag.includes(tagKeyword.value.trim())))
const filteredCustomers = computed(() => customers.value.filter(item => {
  const keyword = archiveKeyword.value.trim(); const matchedKeyword = !keyword || [item.id,item.name,item.phone].some(value => value.includes(keyword))
  return matchedKeyword && (!archiveStatus.value || item.status===archiveStatus.value) && (!archiveStore.value || item.store===archiveStore.value) && (!archiveAdvisor.value || item.advisor===archiveAdvisor.value) && (!archiveTag.value || item.tags.includes(archiveTag.value))
}))
const reportCustomers = computed(() => customers.value.filter(item => item.status === '正常'))
function initializeCustomers(source: Case[]) {
  if (customers.value.length) return
  customers.value = source.map((item, index) => ({ id:`CUS-${String(index + 1).padStart(5, '0')}`, name:item.customer, phone:item.phone, gender:index === 1 ? '男' : '女', birthday:index === 0 ? '1988-06-18' : index === 1 ? '1985-10-09' : '1991-03-26', source:'门店扫码', advisor:index === 0 ? '陈顾问' : '李顾问', store:item.store, level:index === 0 ? 'VIP' : '标准', status:'正常', tags:index === 0 ? ['高消费力','待回访'] : index === 1 ? ['满意度高'] : ['复测意向'] }))
}
function initializeReports() {
  if (reports.value.length || !customers.value.length) return
  reports.value = [
    { id:'RPT-20260725-001', customerId:customers.value[0].id, customerName:customers.value[0].name, questionnaireVersion:'V1.0', description:'睡眠与营养专项测评', sleepQuality:'一般', energyLevel:'偏低', exerciseFrequency:'每周 1-2 次', dietStructure:'外食偏多', primaryNeed:'改善睡眠', historyNote:'无', advisorSummary:'已完成初步访谈并上传检查报告。', attachments:[{name:'体检报告.pdf',type:'application/pdf'},{name:'血检结果.jpg',type:'image/jpeg'}], crossBorder:false, realName:'', realPhone:'', idCard:'', deliveryAddress:'', status:'已完成', assessedAt:'2026-07-25 09:30' },
    { id:'RPT-20260724-002', customerId:customers.value[1].id, customerName:customers.value[1].name, questionnaireVersion:'V1.1', description:'日常健康评估', sleepQuality:'良好', energyLevel:'一般', exerciseFrequency:'每周 3 次', dietStructure:'均衡', primaryNeed:'能量改善', historyNote:'无', advisorSummary:'待补充顾问总结。', attachments:[{name:'检查单.png',type:'image/png'}], crossBorder:true, realName:'周以宁', realPhone:'13900000318', idCard:'310101198510090018', deliveryAddress:'杭州市西湖区演示地址 18 号', status:'测评中', assessedAt:'2026-07-24 13:20' },
    { id:'RPT-20260726-003', customerId:customers.value[2].id, customerName:customers.value[2].name, questionnaireVersion:'V1.1', description:'复测资料暂存', sleepQuality:'', energyLevel:'', exerciseFrequency:'', dietStructure:'', primaryNeed:'', historyNote:'', advisorSummary:'', attachments:[], crossBorder:false, realName:'', realPhone:'', idCard:'', deliveryAddress:'', status:'暂存', assessedAt:'2026-07-26 10:10' },
  ]
}
async function load() { try { cases.value = await api<Case[]>('/api/cases'); initializeCustomers(cases.value); initializeReports(); dashboard.value = await api<any>('/api/dashboard') } catch(e:any) { notice.value=e.message } }
async function setRole(role:Role) { currentRole.value=role; await load(); notice.value=`已切换为${roles.find(x=>x[0]===role)?.[1]}视图` }
function showDetail(item:Case) { active.value=item }
async function pay(item:Case) { try { await api(`/api/cases/${item.id}/pay`,{method:'POST'}); await load(); active.value = cases.value.find(x=>x.id===item.id) || null; notice.value='本地支付回调已确认，订单已进入待生产' } catch(e:any){ notice.value=e.message } }
function startReview(item:Case){ active.value=item; modal.value='review' }
async function submitReview(){ if(!active.value)return; try{ await api(`/api/cases/${active.value.id}/review`,{method:'POST',body:JSON.stringify({approved:reviewApproved.value,comment:reviewComment.value})}); modal.value=''; await load(); active.value=cases.value.find(x=>x.id===active.value?.id)||null; notice.value='审核结果已保存并写入审计日志' }catch(e:any){notice.value=e.message} }
function startFulfill(item:Case, next:string){active.value=item; action.value=next;modal.value='fulfill'}
async function submitFulfill(){if(!active.value)return;try{await api(`/api/cases/${active.value.id}/fulfill`,{method:'POST',body:JSON.stringify({action:action.value})});modal.value='';await load();active.value=cases.value.find(x=>x.id===active.value?.id)||null;notice.value='履约节点已推进'}catch(e:any){notice.value=e.message}}
function operation(item:Case){ if(item.status==='待审核')return '审核方案'; if(item.status==='已生效')return '确认支付'; if(item.status==='待生产')return '开始生产'; if(item.status==='生产中')return '质检放行'; if(item.status==='待质检')return '质量放行'; if(item.status==='待发货')return '发货'; if(item.status==='运输中')return '签收'; return '查看详情' }
function execute(item:Case){ const op=operation(item); if(op==='审核方案')startReview(item); else if(op==='确认支付')pay(item); else if(op==='开始生产')startFulfill(item,'produce'); else if(op==='质检放行')startFulfill(item,'quality'); else if(op==='质量放行')startFulfill(item,'quality'); else if(op==='发货')startFulfill(item,'ship'); else if(op==='签收')startFulfill(item,'sign'); else showDetail(item) }
function openCustomerCreate(){ customerMode.value='create'; customerDraft.value=blankCustomer(); tagKeyword.value=''; modal.value='customer' }
function openCustomerEdit(item: CustomerRecord){ customerMode.value='edit'; customerDraft.value={ ...item, tags:[...item.tags] }; tagKeyword.value=''; modal.value='customer' }
function toggleDraftTag(tag: string){ const tags=customerDraft.value.tags; customerDraft.value.tags=tags.includes(tag) ? tags.filter(item=>item!==tag) : [...tags,tag]; tagKeyword.value='' }
function saveCustomer(){ const draft=customerDraft.value; if(!draft.name.trim() || !/^1\d{10}$/.test(draft.phone)){ notice.value='请填写顾客姓名及正确的 11 位手机号'; return }; if(!draft.store || !draft.advisor){ notice.value='请补充所属门店和归属顾问'; return }; if(customerMode.value==='create'){ customers.value.unshift({ ...draft, id:`CUS-${String(Date.now()).slice(-6)}`, tags:[...draft.tags] }); notice.value='顾客档案已新增并写入本地审计记录' } else { const index=customers.value.findIndex(x=>x.id===draft.id); if(index>=0) customers.value.splice(index,1,{ ...draft, tags:[...draft.tags] }); if(activeCustomer.value?.id===draft.id) activeCustomer.value={ ...draft, tags:[...draft.tags] }; notice.value='顾客档案已更新并写入本地审计记录' }; modal.value='' }
function toggleCustomer(item: CustomerRecord){ item.status=item.status==='正常'?'停用':'正常'; notice.value=`顾客${item.name}已${item.status==='正常'?'启用':'停用'}，操作已记录` }
function deleteCustomer(item: CustomerRecord){ if(item.status!=='停用'){ notice.value='仅停用状态的顾客允许删除'; return }; if(!window.confirm(`确认删除顾客档案“${item.name}”吗？`)) return; customers.value=customers.value.filter(x=>x.id!==item.id); if(activeCustomer.value?.id===item.id) activeCustomer.value=null; notice.value='顾客档案已删除并记录审计日志' }
function openReportCreate(){ reportMode.value='create'; reportDraft.value=blankReport(); reportFormVisible.value=true }
function openReportEdit(item: AssessmentReport){ reportMode.value='edit'; reportDraft.value={ ...item, attachments:[...item.attachments] }; reportFormVisible.value=true }
function syncReportCustomer(){ const customer=customers.value.find(item=>item.id===reportDraft.value.customerId); reportDraft.value.customerName=customer?.name || '' }
function addReportFiles(event: Event){ const files=Array.from((event.target as HTMLInputElement).files || []); reportDraft.value.attachments.push(...files.map(file=>({ name:file.name, type:file.type || '未知类型' }))); (event.target as HTMLInputElement).value='' }
function removeReportFile(index: number){ reportDraft.value.attachments.splice(index,1) }
function validateReport(){ const draft=reportDraft.value; if(!draft.customerId || !draft.questionnaireVersion || !draft.sleepQuality || !draft.energyLevel || !draft.exerciseFrequency || !draft.dietStructure || !draft.primaryNeed || !draft.advisorSummary) return '请完成所有必填测评字段'; if(draft.crossBorder && (!draft.realName || !/^1\d{10}$/.test(draft.realPhone) || !draft.idCard || !draft.deliveryAddress)) return '请完成跨境实名补充信息，并使用本人实名认证手机号'; return '' }
function saveReportDraft(){ const draft={ ...reportDraft.value, attachments:[...reportDraft.value.attachments], status:'暂存' as ReportStatus, assessedAt: reportDraft.value.assessedAt || new Date().toLocaleString('zh-CN',{hour12:false}) }; if(reportMode.value==='create'){ draft.id=`RPT-${String(Date.now()).slice(-10)}`; reports.value.unshift(draft) } else { const index=reports.value.findIndex(item=>item.id===draft.id); if(index>=0) reports.value.splice(index,1,draft) }; reportFormVisible.value=false; notice.value='测评报告已暂存，可继续编辑后提交' }
async function submitReport(){ const message=validateReport(); if(message){ notice.value=message; return }; try{ const response=await api<{id:string;status:ReportStatus;generatedAt:string}>('/api/reports/generate',{method:'POST',body:JSON.stringify({ customerId:reportDraft.value.customerId, questionnaireVersion:reportDraft.value.questionnaireVersion })}); const draft={ ...reportDraft.value, id:reportMode.value==='create'?response.id:reportDraft.value.id, attachments:[...reportDraft.value.attachments], status:response.status, assessedAt:response.generatedAt }; if(reportMode.value==='create') reports.value.unshift(draft); else { const index=reports.value.findIndex(item=>item.id===draft.id); if(index>=0) reports.value.splice(index,1,draft) }; reportFormVisible.value=false; notice.value='报告已由本地服务生成，可进入治疗方案配置' }catch(e:any){ notice.value=e.message } }
function generatePlan(item: AssessmentReport){ if(item.status!=='已完成'){ notice.value='仅已完成测评报告可生成治疗方案'; return }; reportForPlan.value=item; activeReport.value=null; page.value='治疗方案详情' }
function closeModalFromMask(event: MouseEvent){ const target=event.target as HTMLElement; if(!target.classList.contains('modal-mask')) return; modal.value=''; reportFormVisible.value=false }
onMounted(() => { load(); document.addEventListener('click', closeModalFromMask) })
onUnmounted(() => document.removeEventListener('click', closeModalFromMask))
</script>

<template>
  <div class="shell">
    <aside class="side"><div class="brand"><b>LV</b><div><strong>LAVIDA</strong><small>健康管理运营平台</small></div></div>
      <div class="side-foot">本地演示环境<br><span>数据仅用于演示</span></div>
      <SidebarNavigation :groups="groups" :page="page" @select="page = $event" />
    </aside>
    <main><header><div><span class="crumb">LAVIDA / {{ title }}</span><h1>{{ title }}</h1></div><div class="head-actions"><button class="bell" @click="notice = `当前有 ${dashboard.messages?.length || 0} 条待处理提醒`">● {{ dashboard.messages?.length || 0 }}</button><select :value="currentRole" @change="setRole(($event.target as HTMLSelectElement).value as Role)"><option v-for="r in roles" :value="r[0]" :key="r[0]">{{ r[1] }}</option></select></div></header>
      <div v-if="notice" class="toast" @click="notice=''">{{ notice }} ×</div>
      <section class="content">
        <template v-if="page==='工作台'"><div class="hero"><div><span>总部统一服务闭环</span><h2>今天有 {{ dashboard.cards?.[0]?.value || 0 }} 个方案等待专业审核</h2><p>从测评、审核、支付、生产到履约与复测，所有节点均可追溯。</p></div><button @click="page='治疗方案'">处理审核待办 →</button></div><div class="metrics"><article v-for="card in dashboard.cards" :key="card.label"><span>{{ card.label }}</span><b>{{ card.value }}</b><small>较昨日 +12%</small></article></div><div class="two-col"><section class="panel"><h3>业务进度看板</h3><div class="flow-grid"><div v-for="item in cases" :key="item.id" class="flow-card"><div><b>{{ item.customer }}</b><span :class="['tag',item.status]">{{ item.status }}</span></div><p>{{ item.store }} · {{ item.planId }}</p><small>当前操作：{{ item.timeline.at(-1)?.title }} · {{ item.createdAt }}</small><button @click="showDetail(item)">查看业务单</button></div></div></section><section class="panel"><h3>风险预警与待办</h3><ul class="todo"><li v-for="m in dashboard.messages" :key="m.id"><b>{{m.title}}</b><span>{{m.body}}</span></li><li><b>低库存 SKU</b><span>SKU-Q10-08 可用库存 42，建议采购</span></li><li><b>复测提醒</b><span>3 位顾客将在 7 天内到达复测日期</span></li></ul></section></div></template>
        <template v-else-if="page==='测评报告'"><div class="toolbar"><input placeholder="按报告编号或顾客姓名搜索"/><select><option>全部状态</option><option>暂存</option><option>测评中</option><option>已完成</option></select><button class="primary" @click="openReportCreate">+ 新增测评报告</button></div><section class="panel table-panel"><h3>测评报告 <small>报告提交后由本地服务模拟生成，关联治疗方案流程</small></h3><table><thead><tr><th>报告编号</th><th>顾客姓名</th><th>题库版本</th><th>附件数量</th><th>是否跨境</th><th>测评状态</th><th>测评时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in reports" :key="item.id"><td>{{item.id}}</td><td><b>{{item.customerName}}</b></td><td>{{item.questionnaireVersion}}</td><td>{{item.attachments.length}}</td><td>{{item.crossBorder?'是':'否'}}</td><td><span :class="['tag',item.status==='已完成'?'已完成':item.status==='测评中'?'生产中':'待补资料']">{{item.status}}</span></td><td>{{item.assessedAt}}</td><td class="customer-actions"><button @click="activeReport=item">详情</button><button class="link" @click="openReportEdit(item)">编辑</button><button class="link" :disabled="item.status!=='已完成'" @click="generatePlan(item)">生成治疗方案</button></td></tr></tbody></table></section></template>
        <template v-else-if="page==='顾客档案'"><div class="toolbar customer-toolbar"><input v-model="archiveKeyword" placeholder="按顾客姓名、手机号或编号搜索"/><select v-model="archiveStatus"><option value="">全部状态</option><option>正常</option><option>停用</option></select><select v-model="archiveStore"><option value="">全部门店</option><option v-for="store in customerStores" :key="store">{{store}}</option></select><select v-model="archiveAdvisor"><option value="">全部顾问</option><option v-for="advisor in customerAdvisors" :key="advisor">{{advisor}}</option></select><select v-model="archiveTag"><option value="">全部标签</option><option v-for="tag in tagOptions" :key="tag">{{tag}}</option></select><button class="primary" @click="openCustomerCreate">+ 新增顾客</button></div><section class="panel table-panel"><h3>顾客档案 <small>客户标签取自系统设置中的标签参数</small></h3><table><thead><tr><th>编号</th><th>顾客姓名</th><th>所属门店</th><th>归属顾问</th><th>客户状态</th><th>客户标签</th><th>操作</th></tr></thead><tbody><tr v-for="item in filteredCustomers" :key="item.id"><td>{{item.id}}</td><td><b>{{item.name}}</b><br><small>{{item.phone}} · {{item.level}}</small></td><td>{{item.store}}</td><td>{{item.advisor}}</td><td><span :class="['tag', item.status==='正常' ? '已生效' : '待补资料']">{{item.status}}</span></td><td><span v-for="tag in item.tags" :key="tag" class="customer-tag">{{tag}}</span><small v-if="!item.tags.length">未设置</small></td><td class="customer-actions"><button @click="activeCustomer=item">详情</button><button class="link" @click="openCustomerEdit(item)">编辑</button><button class="link" @click="toggleCustomer(item)">{{item.status==='正常'?'停用':'启用'}}</button><button v-if="item.status==='停用'" class="link danger" @click="deleteCustomer(item)">删除</button></td></tr><tr v-if="!filteredCustomers.length"><td colspan="7" class="empty-state">暂无符合条件的顾客档案</td></tr></tbody></table></section></template>
        <template v-else-if="isCasePage"><div class="toolbar"><input placeholder="按顾客、业务单或方案编号搜索"/><select><option>全部状态</option><option>待审核</option><option>生产中</option></select><button class="primary" @click="modal='resource'">+ 新建/处理</button></div><section class="panel table-panel"><h3>{{page}} <small>共享本地数据，切换角色后自动按数据范围过滤</small></h3><table><thead><tr><th>业务编号</th><th>顾客</th><th>门店/加盟商</th><th>风险</th><th>当前状态</th><th>方案/报告</th><th>操作</th></tr></thead><tbody><tr v-for="item in cases" :key="item.id"><td>{{item.id}}</td><td><b>{{item.customer}}</b><br><small>{{item.phone}}</small></td><td>{{item.store}}<br><small>{{item.franchisee}}</small></td><td>{{item.risk}}</td><td><span :class="['tag',item.status]">{{item.status}}</span></td><td>{{item.planId}}<br><small>{{item.reportStatus}}</small></td><td><button @click="showDetail(item)">详情</button><button class="link" @click="execute(item)">{{operation(item)}}</button></td></tr></tbody></table></section></template>
        <template v-else><QuestionBankManagement v-if="page==='测评题库' || page==='题目管理'" :mode="page==='测评题库' ? 'bank' : 'question'"/><template v-else><div class="toolbar"><input :placeholder="`搜索${page}`"/><select><option>全部状态</option><option>启用</option><option>待处理</option></select><button class="primary" @click="modal='resource'">+ 新增{{page}}</button></div><section class="panel generic"><h3>{{page}} <small>已按 LAVIDA 全规格功能配置演示字段</small></h3><div class="setting-grid"><article><b>主数据与配置</b><p>编码、名称、状态、适用范围、版本、更新时间与操作人。</p></article><article><b>权限与审计</b><p>角色、数据范围、字段脱敏、前后值与操作日志。</p></article><article><b>任务与告警</b><p>待办、阈值、负责人、处理状态与升级策略。</p></article></div><table><thead><tr><th>编码</th><th>名称</th><th>分类/属性</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in [['REC-001',page,'演示配置','启用'],['REC-002','默认规则','版本 V1.0','启用'],['REC-003','待处理任务','本地模拟','处理中']]" :key="index"><td v-for="cell in row" :key="cell">{{cell}}</td><td>2026-07-25 11:30</td><td><button @click="modal='resource'">查看/编辑</button></td></tr></tbody></table></section></template></template>
      </section>
    </main>
    <div v-if="page==='治疗方案'" class="treatment-list-overlay"><TreatmentPlanManagement/></div>
    <div v-if="page==='治疗方案详情'" class="plan-page-overlay"><TreatmentPlanDetail :report="reportForPlan" @back="page='测评报告';reportForPlan=null" @saved="notice=$event"/></div>
    <div v-if="reportFormVisible" class="modal-mask"><div class="modal report-form"><button class="close" @click="reportFormVisible=false">×</button><h2>{{reportMode==='create'?'新增测评报告':'编辑测评报告'}}</h2><p>提交后调用本地报告生成接口，生成结果将进入治疗方案流程。</p><div class="report-section"><h3>顾客信息</h3><div class="form-grid"><label>顾客档案 <b class="required">*</b><select v-model="reportDraft.customerId" @change="syncReportCustomer"><option value="">请选择顾客</option><option v-for="customer in reportCustomers" :key="customer.id" :value="customer.id">{{customer.name}} · {{customer.phone}}</option></select></label><label>题库版本 <b class="required">*</b><select v-model="reportDraft.questionnaireVersion"><option>V1.0</option><option>V1.1</option><option>V2.0</option></select></label><label class="form-span">测评说明<textarea v-model="reportDraft.description" rows="2" placeholder="请输入测评说明"></textarea></label></div></div><div class="report-section"><h3>测评问卷</h3><div class="form-grid"><label>近期睡眠质量 <b class="required">*</b><select v-model="reportDraft.sleepQuality"><option value="">请选择</option><option>良好</option><option>一般</option><option>较差</option></select></label><label>日间能量水平 <b class="required">*</b><select v-model="reportDraft.energyLevel"><option value="">请选择</option><option>充沛</option><option>一般</option><option>偏低</option></select></label><label>运动频率 <b class="required">*</b><select v-model="reportDraft.exerciseFrequency"><option value="">请选择</option><option>每周 3 次及以上</option><option>每周 1-2 次</option><option>很少运动</option></select></label><label>饮食结构 <b class="required">*</b><input v-model="reportDraft.dietStructure" placeholder="单选项或文字说明"/></label><label>主要诉求 <b class="required">*</b><input v-model="reportDraft.primaryNeed" placeholder="单选项或文字说明"/></label><label>既往情况说明<input v-model="reportDraft.historyNote" placeholder="选填"/></label><label class="form-span">顾问总结 <b class="required">*</b><textarea v-model="reportDraft.advisorSummary" rows="3" placeholder="请输入顾问总结"></textarea></label></div></div><div class="report-section"><h3>检查附件</h3><div class="attachments"><div v-for="(file,index) in reportDraft.attachments" :key="file.name+index"><span>{{file.name}}</span><small>{{file.type}}</small><button type="button" class="link danger" @click="removeReportFile(index)">删除</button></div><p v-if="!reportDraft.attachments.length">尚未上传附件</p></div><label class="upload-control">上传附件<input type="file" multiple @change="addReportFiles"/></label></div><div class="report-section"><h3>跨境实名补充</h3><label class="radio-line">是否跨境 <b class="required">*</b><input v-model="reportDraft.crossBorder" type="radio" :value="false"/> 否 <input v-model="reportDraft.crossBorder" type="radio" :value="true"/> 是</label><div v-if="reportDraft.crossBorder" class="form-grid"><label>真实姓名 <b class="required">*</b><input v-model="reportDraft.realName" placeholder="请输入真实姓名"/></label><label>手机号 <b class="required">*</b><input v-model="reportDraft.realPhone" placeholder="需由本人身份认证的手机号"/></label><label>身份证号 <b class="required">*</b><input v-model="reportDraft.idCard" placeholder="请输入身份证号"/></label><label>收货地址 <b class="required">*</b><input v-model="reportDraft.deliveryAddress" placeholder="请输入收货地址"/></label></div></div><footer><button @click="reportFormVisible=false">取消</button><button @click="saveReportDraft">暂存</button><button class="primary" @click="submitReport">提交并生成报告</button></footer></div></div>
    <div v-if="activeReport" class="drawer-mask" @click.self="activeReport=null"><aside class="drawer"><button class="close" @click="activeReport=null">×</button><span class="crumb">测评报告详情</span><h2>{{activeReport.customerName}} <em :class="['tag',activeReport.status==='已完成'?'已完成':activeReport.status==='测评中'?'生产中':'待补资料']">{{activeReport.status}}</em></h2><p>{{activeReport.id}} · {{activeReport.questionnaireVersion}} · {{activeReport.assessedAt}}</p><div class="detail-grid"><article><span>睡眠质量</span><b>{{activeReport.sleepQuality || '未填写'}}</b><small>日间能量：{{activeReport.energyLevel || '未填写'}}</small></article><article><span>运动与饮食</span><b>{{activeReport.exerciseFrequency || '未填写'}}</b><small>{{activeReport.dietStructure || '未填写'}}</small></article><article><span>主要诉求</span><b>{{activeReport.primaryNeed || '未填写'}}</b><small>跨境：{{activeReport.crossBorder?'是':'否'}}</small></article></div><h3>检查附件</h3><p>{{activeReport.attachments.map(item=>`${item.name}（${item.type}）`).join('；') || '未上传附件'}}</p><h3>顾问总结</h3><p>{{activeReport.advisorSummary || '未填写'}}</p><h3 v-if="activeReport.crossBorder">跨境实名补充</h3><p v-if="activeReport.crossBorder">{{activeReport.realName}} · {{activeReport.realPhone}} · {{activeReport.idCard}}<br>{{activeReport.deliveryAddress}}</p><footer><button @click="activeReport=null">关闭</button><button class="primary" :disabled="activeReport.status!=='已完成'" @click="generatePlan(activeReport)">生成治疗方案</button></footer></aside></div>
    <div v-if="activeCustomer" class="drawer-mask" @click.self="activeCustomer=null"><aside class="drawer"><button class="close" @click="activeCustomer=null">×</button><span class="crumb">顾客档案详情</span><h2>{{activeCustomer.name}} <em :class="['tag',activeCustomer.status==='正常'?'已生效':'待补资料']">{{activeCustomer.status}}</em></h2><p>{{activeCustomer.id}} · {{activeCustomer.level}} · {{activeCustomer.source}}</p><div class="detail-grid"><article><span>手机号</span><b>{{activeCustomer.phone}}</b><small>{{activeCustomer.gender}} · {{activeCustomer.birthday || '未填写生日'}}</small></article><article><span>所属门店</span><b>{{activeCustomer.store}}</b><small>归属顾问：{{activeCustomer.advisor}}</small></article><article><span>客户标签</span><b>{{activeCustomer.tags.join('、') || '未设置'}}</b><small>来自系统设置标签参数</small></article></div><h3>服务档案</h3><p>顾客基础档案可关联测评、治疗方案、订单、履约与复测服务记录；本演示页仅维护档案主数据。</p><footer><button @click="activeCustomer=null">关闭</button><button class="primary" @click="openCustomerEdit(activeCustomer)">编辑档案</button></footer></aside></div>
    <div v-if="active" class="drawer-mask" @click.self="active=null"><aside class="drawer"><button class="close" @click="active=null">×</button><span class="crumb">业务单详情</span><h2>{{active.customer}} <em :class="['tag',active.status]">{{active.status}}</em></h2><p>{{active.id}} · {{active.store}} · {{active.franchisee}}</p><div class="detail-grid"><article><span>方案</span><b>{{active.planId}}</b><small>{{active.planVersion}}</small></article><article><span>风险</span><b>{{active.risk}}</b><small>{{active.reportStatus}}</small></article><article><span>支付/质检</span><b>{{active.paid?'已支付':'未支付'}}</b><small>{{active.qualityReleased?'已放行':'待放行'}}</small></article></div><h3>方案配方与生产校验</h3><table class="formula"><thead><tr><th>SKU</th><th>占比</th><th>建议用量</th><th>适用原因</th><th>机器参数</th><th>校验</th></tr></thead><tbody><tr v-for="f in active.formula" :key="f.skuCode"><td>{{f.skuCode}}<br><small>{{f.name}}</small></td><td>{{f.ratio}}%</td><td>{{f.dosage}}</td><td>{{f.rationale}}</td><td>{{f.machineParams}}</td><td>有效 / 库存可用</td></tr></tbody></table><h3>全流程时间线</h3><ol class="timeline"><li v-for="t in active.timeline" :key="t.time+t.title"><b>{{t.title}}</b><span>{{t.time}} · {{t.description}}</span></li></ol><footer><button @click="active=null">关闭</button><button class="primary" @click="execute(active)">{{operation(active)}}</button></footer></aside></div>
    <div v-if="modal" class="modal-mask"><div class="modal customer-form"><button class="close" @click="modal=''">×</button><template v-if="modal==='customer'"><h2>{{customerMode==='create'?'新增顾客':'编辑顾客'}}</h2><p>顾客标签由系统设置中心的标签参数统一维护。</p><div class="form-grid"><label>顾客姓名<input v-model="customerDraft.name" placeholder="请输入顾客姓名"/></label><label>手机号<input v-model="customerDraft.phone" maxlength="11" placeholder="请输入手机号"/></label><label>性别<select v-model="customerDraft.gender"><option>未知</option><option>男</option><option>女</option></select></label><label>生日<input v-model="customerDraft.birthday" type="date"/></label><label>来源渠道<select v-model="customerDraft.source"><option>门店扫码</option><option>顾问邀约</option><option>线上咨询</option><option>老客转介绍</option></select></label><label>归属顾问<select v-model="customerDraft.advisor"><option>陈顾问</option><option>李顾问</option><option>王顾问</option></select></label><label>所属门店<select v-model="customerDraft.store"><option>上海静安体验店</option><option>杭州西湖体验店</option><option>北京国贸体验店</option></select></label><label>服务等级<select v-model="customerDraft.level"><option>标准</option><option>VIP</option><option>高净值</option></select></label><label>客户状态<select v-model="customerDraft.status"><option>正常</option><option>停用</option></select></label><label class="form-span">客户标签<div class="tag-picker"><span v-for="tag in customerDraft.tags" :key="tag" class="selected-tag" @click="toggleDraftTag(tag)">{{tag}} ×</span><input v-model="tagKeyword" placeholder="输入内容查询标签"/></div><div v-if="tagKeyword" class="tag-suggestions"><button v-for="tag in filteredTagOptions" :key="tag" type="button" :class="{ selected: customerDraft.tags.includes(tag) }" @mousedown.prevent="toggleDraftTag(tag)">{{tag}}{{customerDraft.tags.includes(tag)?' ✓':''}}</button><span v-if="!filteredTagOptions.length">未找到匹配标签</span></div><small>点击标签可选中；再次点击已选标签可移除。</small></label></div><footer><button @click="modal=''">取消</button><button class="primary" @click="saveCustomer">保存</button></footer></template><template v-else-if="modal==='review'"><h2>专业审核方案</h2><p>审核通过后，顾客才能查看方案并确认订单。</p><label><input type="radio" v-model="reviewApproved" :value="true"/> 审核通过</label><label><input type="radio" v-model="reviewApproved" :value="false"/> 退回补充资料</label><textarea v-model="reviewComment" rows="4" placeholder="审核意见（退回时必填）"></textarea><footer><button @click="modal=''">取消</button><button class="primary" @click="submitReview">提交审核</button></footer></template><template v-else-if="modal==='fulfill'"><h2>推进履约节点</h2><p>将业务单推进为：<b>{{ action==='produce'?'生产中':action==='quality'?'待发货（质检已放行）':action==='ship'?'运输中':'已签收' }}</b></p><textarea placeholder="操作备注与异常说明" rows="4"></textarea><footer><button @click="modal=''">取消</button><button class="primary" @click="submitFulfill">确认处理</button></footer></template><template v-else><h2>{{page}}维护</h2><p>演示表单包含编码、名称、状态、适用范围、配置版本、负责人、备注及审计记录。</p><input placeholder="名称"/><select><option>启用</option><option>停用</option></select><textarea rows="4" placeholder="说明/备注"></textarea><footer><button @click="modal=''">取消</button><button class="primary" @click="modal='';notice='演示数据已保存并记录审计日志'">保存</button></footer></template></div></div>
  </div>
</template>
